const SPECTRUM_REFERENCE = 128;
const BANDS = 64;
const STEP = 1 / 60;
const clamp = v => Math.max(0, Math.min(1, v));
export function spectrumBands(values, output = new Float32Array(BANDS), unit = 'meyda-amplitude') {
    for (let band = 0; band < BANDS; band++) {
        const start = Math.floor((band * values.length) / BANDS),
            end = Math.max(start + 1, Math.floor(((band + 1) * values.length) / BANDS));
        let peak = 0;
        for (let i = start; i < end; i++)
            peak = Math.max(peak, unit === 'signed-waveform' ? Math.abs(values[i] ?? 0) : (values[i] ?? 0));
        output[band] = clamp(
            unit === 'we-strength' || unit === 'signed-waveform'
                ? peak
                : unit === 'byte-frequency'
                  ? peak / 255
                  : Math.log1p(peak) / Math.log1p(SPECTRUM_REFERENCE),
        );
    }
    return output;
}
const fresh = () => ({
    tick: 0,
    position: new Float32Array(BANDS),
    velocity: new Float32Array(BANDS),
    previous: new Float32Array(BANDS),
    levels: new Float32Array(BANDS),
});
const copy = s => ({
    tick: s.tick,
    position: s.position.slice(),
    velocity: s.velocity.slice(),
    previous: s.previous.slice(),
    levels: s.levels.slice(),
});
/** Fixed 60Hz input sampling, two 120Hz integration substeps, one checkpoint per song second. */
export class SpectralStringsState {
    key = '';
    checkpoints = new Map();
    latest = fresh();
    reset() {
        this.key = '';
        this.checkpoints.clear();
        this.latest = fresh();
    }
    resolve(time, key, decay, source, unit = 'meyda-amplitude') {
        if (key !== this.key) {
            this.reset();
            this.key = key;
            this.checkpoints.set(0, fresh());
        }
        const tick = Math.max(0, Math.floor(time * 60 + 1e-8));
        if (this.latest.tick > tick)
            this.latest = copy(this.checkpoints.get(Math.floor(tick / 60) * 60) ?? this.checkpoints.get(0));
        while (this.latest.tick < tick) {
            const s = this.latest;
            spectrumBands(source(s.tick * STEP), s.levels, unit);
            for (let b = 0; b < BANDS; b++) {
                const level = s.levels[b],
                    rise = Math.max(0, level - s.previous[b]);
                s.velocity[b] += rise * (12 + (8 * b) / (BANDS - 1));
                const omega = 7 + (16 * b) / (BANDS - 1),
                    damping = 2 / decay;
                for (let sub = 0; sub < 2; sub++) {
                    const acceleration = -omega * omega * s.position[b] - damping * s.velocity[b];
                    s.velocity[b] += acceleration / 120;
                    s.position[b] += s.velocity[b] / 120;
                }
                s.previous[b] = level;
            }
            s.tick++;
            if (s.tick % 60 === 0) this.checkpoints.set(s.tick, copy(s));
        }
        return this.latest;
    }
}

function createPrimitive(kind) {
    const levels = new Float32Array(64),
        state = new SpectralStringsState();
    return {
        async prepareFrame(frame, input) {
            const p = frame.parameters,
                n = (id, fallback = 0) => (typeof p[id]?.value === 'number' ? p[id].value : fallback);
            const spectrum = Array.isArray(p.spectrum?.value) ? p.spectrum.value : [],
                unit = p.spectrum?.unit ?? 'meyda-amplitude';
            spectrumBands(spectrum, levels, unit);
            let motion = new Float32Array(64);
            if (kind === 1) {
                const key = frame.revision + ':' + frame.seed,
                    target = Math.max(0, Math.floor(frame.time * 60 + 1e-8));
                const start =
                    state.key === key
                        ? state.latest.tick <= target
                            ? state.latest.tick
                            : (state.checkpoints.get(Math.floor(target / 60) * 60)?.tick ?? 0)
                        : 0;
                for (let tick = start; tick < target; tick += 60) {
                    const end = Math.min(target, tick + 60),
                        samples = await input.history({ parameterId: 'spectrum', startTick: tick, endTick: end });
                    const values = new Map(samples.map(s => [Math.round(s.time * 60), s.value]));
                    state.resolve(
                        end / 60,
                        key,
                        n('decay', 0.6),
                        t => values.get(Math.round(t * 60)) ?? spectrum,
                        unit,
                    );
                }
                motion = state.resolve(frame.time, key, n('decay', 0.6), () => spectrum, unit).position;
            }
            return {
                state: Array.from(motion),
                passes: [
                    {
                        program: 'draw',
                        uniforms: {
                            uKind: kind,
                            uViewport: [frame.width, frame.height],
                            uColor: String(p.color?.value ?? '#edf5f1'),
                            uPosition: [n('x', 0.5), n('y', 0.5)],
                            uExtent: [n('width', 1), n('height', 1)],
                            uOpacity: n('opacity', 1),
                            uCount: n('count', 1),
                            uRows: n('rows', 1),
                            uSize: n(kind === 2 ? 'size' : 'thickness', 1),
                            uSpacing: n('spacing', 10),
                            uAmplitude: n('amplitude'),
                            uSensitivity: n('sensitivity', 1),
                            uRadius: n('radius', 0.1),
                            uAmount: n('amount'),
                            uPhase: ((frame.seed % 65536) / 65536) * Math.PI * 2,
                            uLevels: Array.from(levels),
                            uMotion: Array.from(motion),
                        },
                    },
                ],
            };
        },
        reset() {
            state.reset();
        },
        dispose() {
            state.reset();
        },
    };
}

export function create() {
    return createPrimitive(1);
}
